const normalizeSampleValue = (field: OfficialTemplateFieldDefinition) => {
  if (field.key === "recipeLines" && Array.isArray(field.sampleValue)) {
    return field.sampleValue.join("\n");
  }

  if (field.key === "specialMessages" && Array.isArray(field.sampleValue)) {
    return field.sampleValue.join("\n");
  }

  if (field.key === "nutritionTable" && Array.isArray(field.sampleValue)) {
    return field.sampleValue
      .map((entry) =>
        typeof entry === "object" && entry
          ? `${String((entry as { nutrient?: unknown }).nutrient ?? "")}: ${String((entry as { amount?: unknown }).amount ?? "")} | ${String((entry as { dailyValue?: unknown }).dailyValue ?? "")}`
          : String(entry)
      )
      .join("\n");
  }

  if (field.key === "originFooter") {
    return ORIGIN_FOOTER;
  }

  return field.sampleValue;
};

const toDataField = (field: OfficialTemplateFieldDefinition): LabelDataField => ({
  key: field.key,
  label: field.label,
  type: field.schemaCompat?.type ?? "text",
  required: field.required,
  description: field.description,
  sampleValue: normalizeSampleValue(field) as string | number | boolean | undefined,
  fallbackValue:
    field.key === "originFooter" ? ORIGIN_FOOTER : undefined,
  formatType: field.schemaCompat?.formatType,
  formatConfig: field.schemaCompat?.formatConfig
});

