const resolveFormat = (
  template: OfficialTemplateDefinition,
  requestedFormatId?: string,
  requestedOrientation?: DocumentOrientation
): ResolvedPresetFormat => {
  const baseFormat =
    (requestedFormatId ? getLabelFormatById(requestedFormatId) : undefined) ??
    getOfficialTemplateDefaultFormat(template.id) ??
    getLabelFormatById(template.defaultFormatId);

  if (!baseFormat) {
    throw new Error(`Formato base nao encontrado para ${template.id}`);
  }

  const orientation = requestedOrientation ?? template.orientation;
  const isSymmetric =
    baseFormat.widthMm === baseFormat.heightMm || baseFormat.shape === "round";

  const shouldSwap =
    !isSymmetric &&
    ((orientation === "portrait" && baseFormat.widthMm > baseFormat.heightMm) ||
      (orientation === "landscape" && baseFormat.heightMm > baseFormat.widthMm));

  return {
    ...baseFormat,
    resolvedWidthMm: shouldSwap ? baseFormat.heightMm : baseFormat.widthMm,
    resolvedHeightMm: shouldSwap ? baseFormat.widthMm : baseFormat.heightMm,
    resolvedOrientation: orientation
  };
};

type CanvasMetrics = {
  width: number;
  height: number;
  margin: number;
  innerWidth: number;
  innerHeight: number;
};

const getMetrics = (format: ResolvedPresetFormat): CanvasMetrics => {
  const margin = Math.max(2.6, Math.min(format.resolvedWidthMm, format.resolvedHeightMm) * 0.06);
  return {
    width: format.resolvedWidthMm,
    height: format.resolvedHeightMm,
    margin,
    innerWidth: format.resolvedWidthMm - margin * 2,
    innerHeight: format.resolvedHeightMm - margin * 2
  };
};

