import type { BarcodeElement, QrCodeElement } from "./document";

export type BarcodeFormat = BarcodeElement["format"];

export type BarcodeValidationResult = {
  valid: boolean;
  message?: string;
};

const onlyDigits = (value: string) => /^\d+$/.test(value);

export function validateBarcodeValue(
  format: BarcodeFormat,
  value: string
): BarcodeValidationResult {
  const trimmed = value.trim();

  if (!trimmed) {
    return { valid: false, message: "Informe um valor para o codigo de barras." };
  }

  if (format === "EAN13") {
    return /^\d{13}$/.test(trimmed)
      ? { valid: true }
      : { valid: false, message: "EAN13 exige exatamente 13 digitos." };
  }

  if (format === "EAN8") {
    return /^\d{8}$/.test(trimmed)
      ? { valid: true }
      : { valid: false, message: "EAN8 exige exatamente 8 digitos." };
  }

  if (format === "CODE128") {
    return trimmed.length <= 80
      ? { valid: true }
      : { valid: false, message: "CODE128 aceita ate 80 caracteres nesta etiqueta." };
  }

  return { valid: false, message: "Formato de codigo de barras nao suportado." };
}

export function validateQrCodeValue(value: QrCodeElement["value"]): BarcodeValidationResult {
  return value.trim()
    ? { valid: true }
    : { valid: false, message: "Informe um valor para gerar o QR Code." };
}

export function getBarcodeMinimumSize(format: BarcodeFormat) {
  if (format === "EAN13") {
    return { widthMm: 30, heightMm: 12 };
  }

  if (format === "EAN8") {
    return { widthMm: 22, heightMm: 10 };
  }

  return { widthMm: 24, heightMm: 10 };
}

export function normalizeBarcodeText(format: BarcodeFormat, value: string) {
  const trimmed = value.trim();
  return onlyDigits(trimmed) || format === "CODE128" ? trimmed : trimmed.replace(/\s+/g, "");
}
