"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import type { ReactNode } from "react";
import {
  Box,
  Button,
  Container,
  Paper,
  Stack,
  Typography
} from "@mui/material";
import {
  clearSession,
  loadStoredSession,
  sessionHasPermission
} from "../../lib/session";

const items = [
  { href: "/home", label: "Operacao", permission: "template.view" as const },
  { href: "/", label: "Templates", permission: "template.view" as const },
  { href: "/products", label: "Produtos", permission: "product.view" as const },
  { href: "/identity", label: "Identidade", permission: "identity.view" as const },
  { href: "/agents", label: "Agentes", permission: "agent.view" as const },
  { href: "/printers", label: "Impressoras", permission: "printer.view" as const },
  {
    href: "/print-profiles",
    label: "Perfis",
    permission: "print-profile.view" as const
  },
  { href: "/jobs", label: "Jobs", permission: "print-job.view" as const },
  { href: "/audit", label: "Auditoria", permission: "audit.view" as const },
  { href: "/observability", label: "Observabilidade", permission: "observability.view" as const }
];

export function DashboardShell({
  title,
  subtitle,
  action,
  children
}: {
  title: string;
  subtitle: string;
  action?: ReactNode;
  children: ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const session = loadStoredSession();
  const visibleItems = items.filter((item) => sessionHasPermission(session, item.permission));

  return (
    <Box component="main" className="shell" sx={{ p: { xs: 2, md: 3.5 } }}>
      <Container maxWidth={false} disableGutters>
        <Paper sx={{ p: { xs: 2, md: 3 }, display: "grid", gap: 3 }}>
          <Stack
            direction={{ xs: "column", xl: "row" }}
            spacing={3}
            sx={{
              justifyContent: "space-between",
              alignItems: { xs: "stretch", xl: "flex-start" }
            }}
          >
            <Stack spacing={2} sx={{ minWidth: 0 }}>
              <Box
                component="nav"
                sx={{ display: "flex", gap: 1, flexWrap: "wrap" }}
              >
                {visibleItems.map((item) => {
                  const active = pathname === item.href;

                  return (
                    <Button
                      key={item.href}
                      component={Link}
                      href={item.href}
                      variant={active ? "contained" : "text"}
                      color={active ? "primary" : "inherit"}
                      sx={{
                        borderRadius: 999,
                        px: 1.75,
                        color: active ? undefined : "text.secondary",
                        backgroundColor: active ? undefined : "rgba(255,255,255,0.52)"
                      }}
                    >
                      {item.label}
                    </Button>
                  );
                })}
              </Box>

              <Box>
                <Typography variant="overline" color="text.secondary">
                  EasyPrint / Marco 4
                </Typography>
                <Typography variant="h3" component="h1" sx={{ mt: 0.5 }}>
                  {title}
                </Typography>
                <Typography
                  variant="body1"
                  color="text.secondary"
                  sx={{ mt: 1.25, maxWidth: 820 }}
                >
                  {subtitle}
                </Typography>
              </Box>
            </Stack>

            <Stack spacing={1.5} sx={{ alignItems: { xs: "flex-start", xl: "flex-end" } }}>
              <Typography variant="caption" color="text.secondary" sx={{ textAlign: { xl: "right" } }}>
                {session?.session.name ?? "Usuario"} | {session?.session.roleName ?? "Papel"} |{" "}
                {session?.session.tenantSlug ?? "tenant"} |{" "}
                {session?.session.authMethod === "oidc"
                  ? session?.session.externalProviderName ?? "SSO"
                  : "Local"}
              </Typography>
              <Stack direction="row" spacing={1} useFlexGap sx={{ flexWrap: "wrap" }}>
                {action}
                <Button
                  variant="outlined"
                  onClick={() => {
                    clearSession();
                    router.replace("/login");
                  }}
                >
                  Sair
                </Button>
              </Stack>
            </Stack>
          </Stack>

          {children}
        </Paper>
      </Container>
    </Box>
  );
}
