export const OFFICIAL_TEMPLATE_ORDER: OfficialTemplateId[] = [
  "template_60x40_unidade_vertical",
  "vertical_unit_basic",
  "vertical_weight_basic",
  "horizontal_unit_basic",
  "horizontal_weight_basic",
  "horizontal_unit_with_messages",
  "horizontal_weight_with_messages",
  "vertical_unit_with_nutrition",
  "vertical_weight_with_nutrition"
];

export function listOfficialTemplates() {
  return OFFICIAL_TEMPLATE_ORDER.map((id) => OFFICIAL_TEMPLATE_CATALOG[id]);
}

export function getOfficialTemplateById(id: OfficialTemplateId | string) {
  return OFFICIAL_TEMPLATE_CATALOG[id as OfficialTemplateId];
}

export function listOfficialTemplateFields(templateId: OfficialTemplateId | string) {
  const template = getOfficialTemplateById(templateId);
  if (!template) {
    return [];
  }

  return template.fieldKeys.map((key) => OFFICIAL_TEMPLATE_FIELDS[key]);
}

export function listVisibleOfficialTemplateFields(templateId: OfficialTemplateId | string) {
  return listOfficialTemplateFields(templateId).filter((field) => field.visibleInForm);
}

export function listSystemOfficialTemplateFields(templateId: OfficialTemplateId | string) {
  return listOfficialTemplateFields(templateId).filter((field) => field.source !== "user");
}

export function getOfficialTemplateRecommendedFormats(
  templateId: OfficialTemplateId | string
): LabelFormat[] {
  const template = getOfficialTemplateById(templateId);
  if (!template) {
    return [];
  }

  return template.recommendedFormatIds
    .map((formatId) => getLabelFormatById(formatId))
    .filter((format): format is LabelFormat => Boolean(format));
}

export function getOfficialTemplateDefaultFormat(templateId: OfficialTemplateId | string) {
  const template = getOfficialTemplateById(templateId);
  if (!template) {
    return undefined;
  }

  return getLabelFormatById(template.defaultFormatId);
}

export function listOfficialTemplatesByOperationKind(kind: "unit" | "weight") {
  return listOfficialTemplates().filter((template) => template.operationKind === kind);
}

export function listOfficialTemplatesByOrientation(kind: "portrait" | "landscape") {
  return listOfficialTemplates().filter((template) => template.orientation === kind);
}
