import type { ReactNode } from "react";
import { Box, Paper, Stack, Typography, type PaperProps } from "@mui/material";

export function PageSection({
  title,
  description,
  action,
  children,
  contentSx,
  ...paperProps
}: PaperProps & {
  title?: ReactNode;
  description?: ReactNode;
  action?: ReactNode;
  children: ReactNode;
  contentSx?: PaperProps["sx"];
}) {
  return (
    <Paper
      {...paperProps}
      sx={{
        p: { xs: 2, md: 2.5 },
        ...paperProps.sx
      }}
    >
      <Stack spacing={2.25}>
        {title || description || action ? (
          <Stack
            direction={{ xs: "column", md: "row" }}
            spacing={2}
            sx={{
              alignItems: { xs: "flex-start", md: "center" },
              justifyContent: "space-between"
            }}
          >
            <Box>
              {title ? (
                <Typography variant="h5" component="h2">
                  {title}
                </Typography>
              ) : null}
              {description ? (
                <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5, maxWidth: 820 }}>
                  {description}
                </Typography>
              ) : null}
            </Box>
            {action}
          </Stack>
        ) : null}

        <Box sx={contentSx}>{children}</Box>
      </Stack>
    </Paper>
  );
}
